using System.Collections.Generic;
using System.Text;
using UnityEngine;

namespace LastNight.Dialogue
{
    public class DialogueLine
    {
        public string id, chapter, speaker, direction, text;
        public bool leak;
        public AudioClip clip;
    }

    /// <summary>
    /// Loads dialogue.csv (generated by tools/extract_lines.py) and matches audio clips by line ID.
    /// Put VO wav files named &lt;LINE_ID&gt;.wav under a Resources/VO folder, or assign them in voClips.
    /// </summary>
    [CreateAssetMenu(menuName = "Last Night/Dialogue Database")]
    public class DialogueDatabase : ScriptableObject
    {
        [SerializeField] TextAsset dialogueCsv;
        [Tooltip("Optional explicit clips; otherwise loaded from Resources/VO/<id>.")]
        [SerializeField] AudioClip[] voClips;

        Dictionary<string, DialogueLine> lines;

        public DialogueLine Get(string id)
        {
            if (lines == null) Build();
            if (lines.TryGetValue(id, out var line)) return line;
            Debug.LogWarning($"[Dialogue] Unknown line id {id}");
            return null;
        }

        public bool Has(string id)
        {
            if (lines == null) Build();
            return lines.ContainsKey(id);
        }

        void Build()
        {
            lines = new Dictionary<string, DialogueLine>();
            var clips = new Dictionary<string, AudioClip>();
            if (voClips != null)
                foreach (var c in voClips) if (c != null) clips[c.name] = c;

            var rows = ParseCsv(dialogueCsv.text);
            for (int i = 1; i < rows.Count; i++) // skip header
            {
                var r = rows[i];
                if (r.Count < 6) continue;
                var line = new DialogueLine
                {
                    id = r[0], chapter = r[1], speaker = r[2], leak = r[3] == "1", direction = r[4], text = r[5],
                };
                line.clip = clips.TryGetValue(line.id, out var clip) ? clip : Resources.Load<AudioClip>("VO/" + line.id);
                lines[line.id] = line;
            }
        }

        /// <summary>Minimal RFC 4180 CSV parser (quoted fields, escaped quotes, commas in quotes).</summary>
        static List<List<string>> ParseCsv(string text)
        {
            var rows = new List<List<string>>();
            var row = new List<string>();
            var field = new StringBuilder();
            bool quoted = false;
            for (int i = 0; i < text.Length; i++)
            {
                char c = text[i];
                if (quoted)
                {
                    if (c == '"' && i + 1 < text.Length && text[i + 1] == '"') { field.Append('"'); i++; }
                    else if (c == '"') quoted = false;
                    else field.Append(c);
                }
                else if (c == '"') quoted = true;
                else if (c == ',') { row.Add(field.ToString()); field.Clear(); }
                else if (c == '\n')
                {
                    row.Add(field.ToString()); field.Clear();
                    rows.Add(row); row = new List<string>();
                }
                else if (c != '\r') field.Append(c);
            }
            if (field.Length > 0 || row.Count > 0) { row.Add(field.ToString()); rows.Add(row); }
            return rows;
        }
    }
}
